const { useState } = React;

function App() {
  const [page, setPage] = useState("event");
  const [tickets, setTickets] = useState(1);
  const [error, setError] = useState("");

  // Simple ticket options
  const ticketOptions = [1, 2, 3, 4, 5];

  // Handlers
  function handleBookNow(e) {
    e.preventDefault();
    if (tickets < 1) {
      setError("Please select at least one ticket.");
      return;
    }
    setError("");
    setPage("checkout");
  }

  function handleViewVenueMap(e) {
    e.preventDefault();
    setPage("venue");
  }

  // Components for pages
  function EventPage() {
    return (
      <main style={styles.main}>
        <div style={styles.posterContainer}>
          <img
            src="/runtime/photos/product.jpg"
            alt="Jazz Night poster"
            style={styles.poster}
          />
        </div>
        <section style={styles.details}>
          <h2 style={styles.title}>Jazz Night</h2>
          <p style={styles.date}>Sat 12 Dec, 8 PM</p>
          <p style={styles.description}>
            Experience an unforgettable evening of smooth jazz with top artists
            performing live. Enjoy great music, ambiance, and refreshments.
          </p>
          <form onSubmit={handleBookNow} style={styles.form} aria-label="Ticket booking form">
            <label htmlFor="tickets" style={styles.label}>
              Tickets
            </label>
            <select
              id="tickets"
              name="tickets"
              value={tickets}
              onChange={(e) => setTickets(Number(e.target.value))}
              style={styles.select}
            >
              {ticketOptions.map((num) => (
                <option key={num} value={num}>
                  {num}
                </option>
              ))}
            </select>
            <button type="submit" style={styles.bookButton}>
              Book now
            </button>
          </form>
          {error && (
            <p role="alert" style={styles.error}>
              {error}
            </p>
          )}
          <a
            href="#"
            onClick={handleViewVenueMap}
            style={styles.venueLink}
          >
            View venue map
          </a>
        </section>
      </main>
    );
  }

  function CheckoutPage() {
    return (
      <main style={styles.pageCenter}>
        <h2>Checkout</h2>
        <p>You are booking {tickets} ticket{tickets > 1 ? "s" : ""} for Jazz Night.</p>
        <button onClick={() => setPage("event")} style={styles.backButton}>
          Back to event
        </button>
      </main>
    );
  }

  function VenuePage() {
    return (
      <main style={styles.pageCenter}>
        <h2>Venue Map</h2>
        <img
          src="/runtime/photos/building.jpg"
          alt="Venue map"
          style={{ maxWidth: "100%", borderRadius: 8 }}
        />
        <button onClick={() => setPage("event")} style={styles.backButton}>
          Back to event
        </button>
      </main>
    );
  }

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #fefefe;
          color: #222;
        }
        a {
          color: #0066cc;
          text-decoration: none;
          cursor: pointer;
        }
        a:hover, a:focus {
          text-decoration: underline;
          outline: none;
        }
        button {
          cursor: pointer;
          font: inherit;
          border-radius: 6px;
          border: none;
          transition: background-color 0.3s ease;
        }
        button:focus {
          outline: 3px solid #3399ff;
          outline-offset: 2px;
        }
      `}</style>
      <header style={styles.header}>
        <nav style={styles.nav} aria-label="Primary navigation">
          <a href="#" style={styles.logo} onClick={() => setPage("event")}>Eventix</a>
          <div style={styles.navLinks}>
            <a href="#" onClick={() => setPage("event")} style={styles.navLink}>
              Events
            </a>
            <a href="#" onClick={() => setPage("venue")} style={styles.navLink}>
              Venues
            </a>
            <a href="#" onClick={() => alert("My tickets page not implemented") } style={styles.navLink}>
              My tickets
            </a>
          </div>
        </nav>
      </header>
      {page === "event" && <EventPage />}
      {page === "checkout" && <CheckoutPage />}
      {page === "venue" && <VenuePage />}
    </>
  );
}

